import{_ as t,c as a,o,ag as i}from"./chunks/framework.BwVZiZlf.js";const f=JSON.parse('{"title":"Life is movement","description":"","frontmatter":{"date":"2025-04-06T00:00:00.000Z"},"headers":[],"relativePath":"blog/2025/04/06/Life-is-movement.md","filePath":"blog/2025/04/06/Life-is-movement.md","lastUpdated":1786675408000}'),n={name:"blog/2025/04/06/Life-is-movement.md"};function s(r,e,h,l,d,m){return o(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1743897600000"},e[0]||(e[0]=[i('<h1 id="life-is-movement" tabindex="-1">Life is movement <a class="header-anchor" href="#life-is-movement" aria-label="Permalink to &quot;Life is movement&quot;">​</a></h1><h2 id="never-lose-your-temper-with-your-child" tabindex="-1">Never lose your temper with your child <a class="header-anchor" href="#never-lose-your-temper-with-your-child" aria-label="Permalink to &quot;Never lose your temper with your child&quot;">​</a></h2><p>I’m working on it.</p><p>This morning, I got up at 5:30 AM to cook breakfast for my son, as he needs to be at school by 8:10 AM. I don&#39;t want him to be late.</p><p>Last time, I got very angry because he did things so slowly, and as a result, he was late for class. I&#39;ve read The Courage to Be Disliked before, and I realized my outburst was a mistake — it may have left a shadow on my child&#39;s heart.</p><p>This time, he still ate breakfast slowly, though it was better than last time. And I knew I shouldn&#39;t get angry with him, because I had done my part (what I was supposed to do). If he didn’t do his part, then he would have to take responsibility — the responsibility for being late.</p><p>So I let it go and calmly reminded him that if he didn’t hurry up, he would definitely be late.</p><h2 id="life-is-movement-1" tabindex="-1">Life is Movement <a class="header-anchor" href="#life-is-movement-1" aria-label="Permalink to &quot;Life is Movement&quot;">​</a></h2><p>This afternoon, I played football with some kids, including mine. I had a great time with these kids; I felt the beauty of life, the power of youth, and the dopamine rush from the exercise. I took some photos, and the smiles on the children’s faces were truly joyful.</p><p>I saw a BBC documentary recently that reminded me how hard life can be, how nature is full of competition — even between mother and daughter. The playful moments between parents and their young are so precious — and it’s the same for us humans. Children grow up so quickly and eventually leave us to explore their own world.</p><p>Whenever possible, I want to make time each day to exercise with my child — whether it’s running, biking, swimming, hiking, or anything else active. These are moments worth cherishing. The most precious times in life are often found in those beautiful moments of shared activity and connection.</p>',11)]))}const p=t(n,[["render",s]]);export{f as __pageData,p as default};
